private url(sheet: string): string {
  return `/api/sheets/${encodeURIComponent(sheet)}/pools`;
}

private async load(sheet: string): Promise<void> {
  const l = await firstValueFrom(this.http.get<PoolView[]>(this.url(sheet)));
  if (this.session.sheetId() === sheet) this.pools.set(l);
}

// The latest history read asked for: an earlier one answering after it is dropped.
private historyReads = 0;

private async loadHistory(sheet: string): Promise<void> {
  const read = ++this.historyReads;
  const h = await firstValueFrom(
    this.http.get<PeriodPools[]>(`${this.url(sheet)}/history`, { context: new HttpContext().set(LIVE, true) }),
  );
  if (this.session.sheetId() === sheet && read === this.historyReads) this.store.history.set(h);
}

/**
 * Downloads the pools as a CSV file: one line per member, pools in the order added and members in the order added,
 * a pool member as pool:<name>, the cut as shown (empty when none).
 */
protected async exportPools(): Promise<void> {
  await this.session.settled();
  const lines = [['pool', 'member', 'share', 'cut']];
  for (const p of this.shown())
    for (const m of p.members) lines.push([p.name, m.poolId !== null ? `pool:${m.name}` : m.name, m.share, m.cut]);
  const csv = lines.map((fields) => fields.map(csvField).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
  const link = this.document.createElement('a');
  link.href = url;
  link.download = 'pools.csv';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url));
}

